<?php declare(strict_types=1);
$ruleBlocked=false;$ruleForm=[];$ruleVersion=(string)$rulesState['version'];
if(($_POST['action']??null)==='save-anniversary-rules'){
 try{$draft=$occasionRuleDraft??\Kulturhus\Verein\Web\OccasionForm::draft($_GET,$_POST);$ruleForm=$draft['rows'];$ruleVersion=$draft['version'];}catch(DomainException){$ruleBlocked=true;}
 if($error!==''&&in_array(http_response_code(),[403,404,409,500,503],true))$ruleBlocked=true;
}else foreach($rulesState['rules']as$rule)$ruleForm[]=['name'=>$occasionRuleName($rule['name'],(int)$rule['months']),'duration'=>$rule['months']%12===0?(string)($rule['months']/12):(string)$rule['months'],'unit'=>$rule['months']%12===0?'years':'months'];
$ruleClose=url($occasionState['route']);$ruleAction=url($occasionState['route']+['edit_rules'=>'1']);
$renderRule=static function(array$rule,int$i)use($ot):void{?>
<div class="anniversary-rule"><label><?=e($ot('Name'))?><input class="form-control" name="rule_name[]" maxlength="100" value="<?=e($rule['name'])?>"></label><label><?=e($ot('Dauer'))?><input class="form-control" name="rule_duration[]" inputmode="numeric" value="<?=e($rule['duration'])?>"></label><label><?=e($ot('Einheit'))?><select class="form-control" name="rule_unit[]"><?php if(!in_array($rule['unit'],['years','months'],true)):?><option value="<?=e($rule['unit'])?>" selected><?=e($rule['unit'])?></option><?php endif?><option value="years" <?=$rule['unit']==='years'?'selected':''?>><?=e($ot('Jahre'))?></option><option value="months" <?=$rule['unit']==='months'?'selected':''?>><?=e($ot('Monate'))?></option></select></label><button type="submit" name="rule_edit" value="remove:<?=$i?>" class="btn btn-outline theme-secondary icon-button" data-remove-rule formnovalidate aria-label="<?=e($ot('Jubiläumsregel entfernen'))?>">×</button></div>
<?php };
?>
<dialog open class="side-sheet" data-modal data-occasion-rule-dialog data-close-url="<?=e($ruleClose)?>" aria-labelledby="anniversary-title"><form method="post" action="<?=e($ruleAction)?>" data-occasion-rules><?=csrf().hidden('action','save-anniversary-rules').hidden('occasion_complete','1').hidden('version',$ruleVersion)?><header><h2 id="anniversary-title"><?=e($ot('Jubiläen'))?></h2><a href="<?=e($ruleClose)?>" aria-label="<?=e($ot('Jubiläumsregeln schließen'))?>">×</a></header><div class="sheet-content"><p><?=e($ot('Lege fest, welche Mitgliedschaftsdauern in der Jubiläumsliste und im Dashboard erscheinen.'))?></p>
<?php if($error!==''):?><p class="error" role="alert"><?=e($ot($error))?></p><?php endif?>
<?php if($ruleBlocked):?><p role="status"><?=e($ot('Die ursprünglichen Angaben bleiben gesperrt lesbar. Aktuellen Speicherstand vor einer neuen Änderung bewusst prüfen.'))?></p><a class="btn btn-outline" target="_blank" rel="noopener" href="<?=e($ruleAction)?>"><?=e($ot('Gespeicherte Regeln in neuem Fenster prüfen'))?></a><?php endif?>
<fieldset <?=$ruleBlocked?'disabled':''?>><div data-rule-list><?php foreach($ruleForm as$i=>$rule)$renderRule($rule,$i);?></div><button type="submit" name="rule_edit" value="add" class="btn btn-outline theme-secondary secondary" data-add-rule formnovalidate><?=e($ot('Weiteres Jubiläum hinzufügen'))?></button><p class="muted"><?=e($ot('Bis zu 24 Regeln. Das Entfernen einer Regel verändert keine Mitgliedschaft.'))?></p><p class="muted"><?=e($ot('Hinzufügen und Entfernen bearbeiten nur diesen Entwurf. Erst Speichern übernimmt die Regeln.'))?></p></fieldset>
<?php if($ruleBlocked):?><?php endif?>
</div><footer><a class="btn btn-outline theme-secondary button secondary" href="<?=e($ruleClose)?>"><?=e($ot('Abbrechen'))?></a><?php if(!$ruleBlocked):?><button class="btn btn-solid theme-primary"><?=e($ot('Jubiläumsregeln speichern'))?></button><?php endif?></footer></form></dialog>
<template id="anniversary-rule-template"><?php $renderRule(['name'=>'','duration'=>'','unit'=>'years'],0);?></template>
